package com.nexus.rtp.fraud.model;

import com.fasterxml.jackson.annotation.JsonProperty;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.io.Serializable;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;
import java.util.Map;

/**
 * Represents a fraud alert generated by the detection system.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class FraudAlert implements Serializable {
    
    private static final long serialVersionUID = 1L;
    
    @JsonProperty("alertId")
    private String alertId;
    
    @JsonProperty("transactionId")
    private String transactionId;
    
    @JsonProperty("uetr")
    private String uetr;
    
    @JsonProperty("accountId")
    private String accountId;
    
    @JsonProperty("alertType")
    private AlertType alertType;
    
    @JsonProperty("severity")
    private String severity;
    
    @JsonProperty("score")
    private double score;
    
    @JsonProperty("description")
    private String description;
    
    @JsonProperty("ruleId")
    private String ruleId;
    
    @JsonProperty("ruleName")
    private String ruleName;
    
    @JsonProperty("amount")
    private BigDecimal amount;
    
    @JsonProperty("currency")
    private String currency;
    
    @JsonProperty("detectedAt")
    private Instant detectedAt;
    
    @JsonProperty("transactionTimestamp")
    private Instant transactionTimestamp;
    
    @JsonProperty("relatedTransactions")
    private List<String> relatedTransactions;
    
    @JsonProperty("indicators")
    private Map<String, Object> indicators;
    
    @JsonProperty("recommendation")
    private String recommendation;
    
    @JsonProperty("status")
    private AlertStatus status;
    
    /**
     * Alert types for different fraud patterns.
     */
    public enum AlertType {
        VELOCITY,           // High transaction frequency
        SMURFING,           // Structuring to avoid thresholds
        GEO_ANOMALY,        // Impossible travel / location anomaly
        AMOUNT_ANOMALY,     // Unusual transaction amount
        BEHAVIORAL,         // ML-based behavioral anomaly
        SANCTIONS_MATCH,    // Potential sanctions hit
        DEVICE_ANOMALY,     // New/suspicious device
        NETWORK_FRAUD       // Connected to known fraud accounts
    }
    
    /**
     * Alert status for workflow tracking.
     */
    public enum AlertStatus {
        NEW,
        UNDER_REVIEW,
        CONFIRMED_FRAUD,
        FALSE_POSITIVE,
        ESCALATED,
        RESOLVED
    }
    
    /**
     * Calculate severity based on score.
     */
    public static String calculateSeverity(double score) {
        if (score >= 0.9) return "CRITICAL";
        if (score >= 0.7) return "HIGH";
        if (score >= 0.5) return "MEDIUM";
        return "LOW";
    }
    
    /**
     * Create a velocity alert.
     */
    public static FraudAlert createVelocityAlert(
            PaymentEvent event,
            int transactionCount,
            BigDecimal totalAmount,
            double score
    ) {
        return FraudAlert.builder()
                .alertId(java.util.UUID.randomUUID().toString())
                .transactionId(event.getTransactionId())
                .uetr(event.getUetr())
                .accountId(event.getDebtorAccountId())
                .alertType(AlertType.VELOCITY)
                .severity(calculateSeverity(score))
                .score(score)
                .description(String.format(
                        "Unusual velocity detected: %d transactions totaling %s %s in 5 minutes",
                        transactionCount, totalAmount.toPlainString(), event.getCurrency()
                ))
                .ruleId("VEL-001")
                .ruleName("Transaction Velocity Check")
                .amount(event.getAmount())
                .currency(event.getCurrency())
                .detectedAt(Instant.now())
                .transactionTimestamp(event.getTimestamp())
                .indicators(Map.of(
                        "transactionCount", transactionCount,
                        "totalAmount", totalAmount.doubleValue(),
                        "windowMinutes", 5
                ))
                .recommendation("Review recent account activity and consider temporary hold")
                .status(AlertStatus.NEW)
                .build();
    }
    
    /**
     * Create a smurfing alert.
     */
    public static FraudAlert createSmurfingAlert(
            List<PaymentEvent> transactions,
            BigDecimal totalAmount,
            BigDecimal threshold,
            double score
    ) {
        PaymentEvent lastEvent = transactions.get(transactions.size() - 1);
        List<String> relatedTxIds = transactions.stream()
                .map(PaymentEvent::getTransactionId)
                .toList();
        
        return FraudAlert.builder()
                .alertId(java.util.UUID.randomUUID().toString())
                .transactionId(lastEvent.getTransactionId())
                .uetr(lastEvent.getUetr())
                .accountId(lastEvent.getDebtorAccountId())
                .alertType(AlertType.SMURFING)
                .severity(calculateSeverity(score))
                .score(score)
                .description(String.format(
                        "Possible smurfing detected: %d transactions totaling %s %s, exceeding threshold of %s",
                        transactions.size(), totalAmount.toPlainString(), lastEvent.getCurrency(),
                        threshold.toPlainString()
                ))
                .ruleId("SMF-001")
                .ruleName("Smurfing Pattern Detection")
                .amount(totalAmount)
                .currency(lastEvent.getCurrency())
                .detectedAt(Instant.now())
                .transactionTimestamp(lastEvent.getTimestamp())
                .relatedTransactions(relatedTxIds)
                .indicators(Map.of(
                        "transactionCount", transactions.size(),
                        "totalAmount", totalAmount.doubleValue(),
                        "threshold", threshold.doubleValue(),
                        "averageAmount", totalAmount.divide(
                                BigDecimal.valueOf(transactions.size()), 2, java.math.RoundingMode.HALF_UP
                        ).doubleValue()
                ))
                .recommendation("Investigate for potential structuring activity")
                .status(AlertStatus.NEW)
                .build();
    }
    
    /**
     * Create a geographic anomaly alert.
     */
    public static FraudAlert createGeoAnomalyAlert(
            PaymentEvent currentEvent,
            PaymentEvent previousEvent,
            double distanceKm,
            double hoursElapsed,
            double requiredSpeedKmh
    ) {
        double score = Math.min(1.0, requiredSpeedKmh / 1000.0); // Higher speed = higher score
        
        return FraudAlert.builder()
                .alertId(java.util.UUID.randomUUID().toString())
                .transactionId(currentEvent.getTransactionId())
                .uetr(currentEvent.getUetr())
                .accountId(currentEvent.getDebtorAccountId())
                .alertType(AlertType.GEO_ANOMALY)
                .severity(calculateSeverity(score))
                .score(score)
                .description(String.format(
                        "Impossible travel detected: %.0f km in %.1f hours (would require %.0f km/h)",
                        distanceKm, hoursElapsed, requiredSpeedKmh
                ))
                .ruleId("GEO-001")
                .ruleName("Impossible Travel Detection")
                .amount(currentEvent.getAmount())
                .currency(currentEvent.getCurrency())
                .detectedAt(Instant.now())
                .transactionTimestamp(currentEvent.getTimestamp())
                .relatedTransactions(List.of(previousEvent.getTransactionId()))
                .indicators(Map.of(
                        "distanceKm", distanceKm,
                        "hoursElapsed", hoursElapsed,
                        "requiredSpeedKmh", requiredSpeedKmh,
                        "currentCountry", currentEvent.getDebtorCountry(),
                        "previousCountry", previousEvent.getDebtorCountry()
                ))
                .recommendation("Verify account holder location and consider blocking account")
                .status(AlertStatus.NEW)
                .build();
    }
    
    /**
     * Create an amount anomaly alert.
     */
    public static FraudAlert createAmountAnomalyAlert(
            PaymentEvent event,
            BigDecimal averageAmount,
            BigDecimal stdDev,
            double zScore
    ) {
        double score = Math.min(1.0, Math.abs(zScore) / 5.0);
        
        return FraudAlert.builder()
                .alertId(java.util.UUID.randomUUID().toString())
                .transactionId(event.getTransactionId())
                .uetr(event.getUetr())
                .accountId(event.getDebtorAccountId())
                .alertType(AlertType.AMOUNT_ANOMALY)
                .severity(calculateSeverity(score))
                .score(score)
                .description(String.format(
                        "Unusual transaction amount: %s %s (%.1f standard deviations from average of %s)",
                        event.getAmount().toPlainString(), event.getCurrency(),
                        zScore, averageAmount.toPlainString()
                ))
                .ruleId("AMT-001")
                .ruleName("Amount Anomaly Detection")
                .amount(event.getAmount())
                .currency(event.getCurrency())
                .detectedAt(Instant.now())
                .transactionTimestamp(event.getTimestamp())
                .indicators(Map.of(
                        "transactionAmount", event.getAmount().doubleValue(),
                        "averageAmount", averageAmount.doubleValue(),
                        "standardDeviation", stdDev.doubleValue(),
                        "zScore", zScore
                ))
                .recommendation("Verify transaction with account holder")
                .status(AlertStatus.NEW)
                .build();
    }
}
